class TFMRequestInventDimElement extends TFMRequestElement
{

    WMSLocationId               fromWmsLocation;
    WMSLocationId               toWMSLocation;
    WMSLocationId               wmsLocation;
    InventLocationId            location;
    InventLocationId            Fromlocation;
    InventLocationId            Tolocation;
    InventBatchId               batchId;
    InventSerialId              serialId;
    TransDate                   expirationDate;
    EcoResItemConfigurationName conFigId;
    EcoResItemColorName         color;
    EcoResItemSizeName          size;
    EcoResItemStyleName         style;
    WHSLicensePlateId           licensePlate;
    WHSLicensePlateId           toLicensePlate;

}

