public InventDim createInventDim(InventDim _inventDim)
{        
    return InventDim::findOrCreate(TFMInventDimHelper::getInventDim(_inventDim,itemId,this));        
}

public InventDim createFromInventDim(InventDim _inventDim)
{
    return TFMInventDimHelper::getInventDim(_inventDim,itemId,this,'From');
}

public InventDim createToInventDim(InventDim _inventDim)
{
    return TFMInventDimHelper::getInventDim(_inventDim,itemId,this,'To');
}

