protected void updateItemId(str _inputStr)
{
    super(_inputStr);
    if(itemId)
    {
        // When the item id is set we make sure the InventDim is set.
        TFMHelper::EnsureInventDim(inventDim);
        inventDim = this.createInventDim(inventDim);
        this.parmInventDim(inventDim);
    }
}
